import { test } from "node:test";
import assert from "node:assert/strict";
import { isEnabled, type FlagConfig } from "../src/flags/evaluate.ts";
import { FlagStore } from "../src/flags/store.ts";
import { assignVariant } from "../src/flags/variants.ts";
import { flagsForRequest, type Exposure } from "../src/flags/requestFlags.ts";

const users = Array.from({ length: 2000 }, (_, i) => `user-${i}`);
const flag = (over: Partial<FlagConfig> = {}): FlagConfig => ({
    key: "new-checkout",
    enabled: true,
    rolloutPercent: 0,
    allowUsers: [],
    denyUsers: [],
    ...over,
});
const share = (f: FlagConfig) => users.filter((u) => isEnabled(f, u)).length / users.length;

test("a 0% rollout enables nobody", () => {
    const on = users.filter((u) => isEnabled(flag({ rolloutPercent: 0 }), u));
    console.log(`0% rollout enabled ${on.length} of ${users.length} users`);
    assert.equal(on.length, 0);
});

test("a 100% rollout enables everyone; 25% about a quarter, the same users every time", () => {
    assert.equal(share(flag({ rolloutPercent: 100 })), 1);
    const f = flag({ rolloutPercent: 25 });
    const s = share(f);
    assert.ok(s > 0.2 && s < 0.3, `got ${s}`);
    assert.deepEqual(users.map((u) => isEnabled(f, u)), users.map((u) => isEnabled(f, u)));
});

test("1% means about 1%, not 2%", () => {
    const s = share(flag({ rolloutPercent: 1 }));
    assert.ok(s > 0.004 && s < 0.016, `got ${s}`);
});

test("allow and deny lists, and the kill switch", () => {
    assert.equal(isEnabled(flag({ allowUsers: ["user-7"] }), "user-7"), true);
    assert.equal(isEnabled(flag({ rolloutPercent: 100, denyUsers: ["user-7"] }), "user-7"), false);
    assert.equal(isEnabled(flag({ enabled: false, allowUsers: ["user-7"] }), "user-7"), false);
});

test("FlagStore keeps the last good config when a reload is malformed", () => {
    const store = new FlagStore();
    store.load(JSON.stringify([flag({ rolloutPercent: 100 })]));
    assert.throws(() => store.load("{not json"));
    assert.equal(store.isEnabled("new-checkout", "user-1"), true);
});

test("experiment variants are sticky and follow their weights", () => {
    const exp = { key: "pricing-page", variants: [{ name: "control", weight: 50 }, { name: "annual-first", weight: 30 }, { name: "no-free-tier", weight: 20 }] };
    const counts: Record<string, number> = {};
    for (const u of users) counts[assignVariant(exp, u)] = (counts[assignVariant(exp, u)] ?? 0) + 1;
    assert.ok(counts.control > 900 && counts.control < 1100, JSON.stringify(counts));
    assert.ok(counts["no-free-tier"] > 320 && counts["no-free-tier"] < 480, JSON.stringify(counts));
    assert.equal(assignVariant(exp, "user-42"), assignVariant(exp, "user-42"));
    assert.throws(() => assignVariant({ key: "empty", variants: [{ name: "a", weight: 0 }] }, "u"));
});

test("a page's flags at 0% are off for every signed-in user, and every evaluation is reported", () => {
    const store = new FlagStore();
    store.load(JSON.stringify([flag({ key: "new-checkout", rolloutPercent: 0 }), flag({ key: "dark-mode", rolloutPercent: 100 })]));
    const exposures: Exposure[] = [];
    const leaked = users.filter((u) => flagsForRequest(store, u, ["new-checkout", "dark-mode"], (e) => exposures.push(e))["new-checkout"]);
    assert.equal(leaked.length, 0);
    assert.equal(exposures.length, users.length * 2);
});

test("anonymous visitors get every flag off and produce no exposures", () => {
    const store = new FlagStore();
    store.load(JSON.stringify([flag({ key: "dark-mode", rolloutPercent: 100 })]));
    const exposures: Exposure[] = [];
    assert.deepEqual(flagsForRequest(store, null, ["dark-mode", "dark-mode"], (e) => exposures.push(e)), { "dark-mode": false });
    assert.deepEqual(exposures, []);
});
